using System;
using System.IO;
using System.Text;
using System.Threading;
using System.Collections.Generic;
using System.Linq;
using System.Web.Script.Serialization;
using PlayDo.Odometer;
class Tests {
 static int passed, failed;
 static void Check(string name, Action test) { try {test();passed++;Console.WriteLine("PASS " + name);}catch(Exception e){failed++;Console.WriteLine("FAIL " + name + ": " + e);} }
 static void Eq(long actual,long expected) { if(actual!=expected)throw new Exception("expected "+expected+", got "+actual); }
 static string Event(long input,long output,string at,long lastInput,long cached,string quota) {
  return "{\"type\":\"event_msg\",\"timestamp\":\""+at+"\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":"+input+",\"cached_input_tokens\":"+cached+",\"output_tokens\":"+output+",\"reasoning_output_tokens\":2},\"last_token_usage\":{\"input_tokens\":"+lastInput+",\"output_tokens\":5,\"cached_input_tokens\":0}},\"rate_limits\":"+quota+"}}";
 }
 static string E(long i,long o,string t) { return Event(i,o,t,i,0,"null"); }
 static string Meta(string type,string at,string model,string cwd){return new JavaScriptSerializer().Serialize(new {type=type,timestamp=at,payload=new {model=model,cwd=cwd}});}
 static Tokens Group(Dictionary<string,BreakdownUsage> groups,string id,DateTime start){return UsageLedger.TotalForDays(groups[id].Days,start);}
 static int Main() {
  const string a="2026-10-17T14:00:00Z",b="2026-10-17T14:01:00Z",c="2026-10-17T14:02:00Z";
  Check("usage totals keep cached input a subset",delegate{var l=new UsageLedger();l.Accept("s",Event(100,5,a,100,80,"null"));Eq(l.TotalFor(DateTime.MinValue).Total,105);Eq(l.TotalFor(DateTime.MinValue).Cached,80);});
  Check("duplicate cumulative snapshots add zero",delegate{var l=new UsageLedger();l.Accept("s",E(100,5,a));l.Accept("s",E(100,5,b));l.Accept("s",E(150,10,c));Eq(l.TotalFor(DateTime.MinValue).Total,160);});
  Check("counter reset counts only last call",delegate{var l=new UsageLedger();l.Accept("s",E(1000,5,a));l.Accept("s",Event(300,50,b,20,0,"null"));Eq(l.TotalFor(DateTime.MinValue).Total,1030);});
  Check("fork replay is not double counted",delegate{var l=new UsageLedger();l.Accept("s",E(100,5,a));l.Accept("fork",E(100,5,a));l.Accept("fork",E(130,10,b));Eq(l.TotalFor(DateTime.MinValue).Total,140);});
  Check("quoted usage in tool content cannot count",delegate{var l=new UsageLedger();l.Accept("s","{\"type\":\"response_item\",\"payload\":{\"type\":\"token_count\"}}");l.Accept("s","{broken");Eq(l.Events,0);});
  Check("older replay cannot rewind session baseline",delegate{var l=new UsageLedger();l.Accept("s",E(100,5,a));l.Accept("s",E(150,10,b));l.Accept("s",E(100,5,a));l.Accept("s",E(180,15,c));Eq(l.TotalFor(DateTime.MinValue).Total,195);});
  Check("same timestamp replay cannot rewind baseline",delegate{var l=new UsageLedger();l.Accept("s",E(100,5,a));l.Accept("s",E(150,10,a));l.Accept("s",E(100,5,a));l.Accept("s",E(180,15,b));Eq(l.TotalFor(DateTime.MinValue).Total,195);});
  Check("first event uses last call when earlier history is missing",delegate{var l=new UsageLedger();l.Accept("s",Event(100000,50,a,12,0,"null"));Eq(l.TotalFor(DateTime.MinValue).Total,17);});
  Check("quota windows retain real lengths and newest timestamp",delegate{var l=new UsageLedger();string q="{\"limit_id\":\"codex\",\"primary\":{\"used_percent\":37,\"window_minutes\":10080,\"resets_at\":1792874453},\"secondary\":null}";l.Accept("s",Event(100,5,b,100,0,q));l.Accept("s",E(100,5,c));if(l.LatestQuota==null)throw new Exception("missing quota");Eq(l.LatestQuota.Windows[0].Minutes,10080);Eq((long)l.LatestQuota.Windows[0].Used,37);});
  Check("64 bit counters",delegate{var l=new UsageLedger();l.Accept("s",E(3000000000,5,a));Eq(l.TotalFor(DateTime.MinValue).Total,3000000005);});
  Check("daily scope filters history",delegate{var l=new UsageLedger();l.Accept("s",E(100,5,"2026-10-15T12:00:00Z"));l.Accept("s",E(150,10,b));Eq(l.TotalFor(new DateTime(2026,10,17)).Total,55);});
  Check("metadata before first usage preserves missing-history baseline",delegate{var l=new UsageLedger();l.Accept("s",Meta("turn_context",a,"gpt-6.1-sol",@"C:\Work\Alpha"));l.Accept("s",Event(100000,50,b,12,0,"null"));Eq(l.TotalFor(DateTime.MinValue).Total,17);Eq(Group(l.Models,"gpt-6.1-sol",DateTime.MinValue).Total,17);});
  Check("model switches attribute only subsequent accepted deltas",delegate{var l=new UsageLedger();l.Accept("s",Meta("turn_context",a,"gpt-a",null));l.Accept("s",E(100,5,a));l.Accept("s",Meta("turn_context",b,"gpt-b",null));l.Accept("s",E(150,10,b));Eq(Group(l.Models,"gpt-a",DateTime.MinValue).Total,105);Eq(Group(l.Models,"gpt-b",DateTime.MinValue).Total,55);});
  Check("cwd metadata is ignored and never retained in the serialized ledger",delegate{var l=new UsageLedger();l.Accept("s",Meta("session_meta",a,null,@"C:\SensitiveFolder\Alpha"));Eq(l.Sessions.Count,0);l.Accept("s",Meta("turn_context",b,"gpt-a",@"C:\SensitiveFolder\Beta"));l.Accept("s",E(100,5,b));string json=new JavaScriptSerializer().Serialize(l);if(json.IndexOf("SensitiveFolder",StringComparison.Ordinal)>=0||json.IndexOf("Project",StringComparison.Ordinal)>=0||json.IndexOf("cwd",StringComparison.OrdinalIgnoreCase)>=0)throw new Exception("cwd retained");Eq(Group(l.Models,"gpt-a",DateTime.MinValue).Total,105);});
  Check("missing metadata uses Unknown and nested metadata cannot impersonate context",delegate{var l=new UsageLedger();l.Accept("s","{\"type\":\"response_item\",\"payload\":{\"type\":\"turn_context\",\"model\":\"fake\",\"cwd\":\"C:\\\\Fake\"}}");l.Accept("s",E(100,5,a));Eq(Group(l.Models,UsageLedger.UnknownId,DateTime.MinValue).Total,105);Eq(l.Models.Count,1);});
  Check("replayed records cannot reattribute already counted usage",delegate{var l=new UsageLedger();l.Accept("s",Meta("turn_context",a,"gpt-a",@"C:\Alpha"));l.Accept("s",E(100,5,a));l.Accept("fork",Meta("turn_context",a,"gpt-b",@"C:\Beta"));l.Accept("fork",E(100,5,a));Eq(l.Models.Count,1);Eq(Group(l.Models,"gpt-a",DateTime.MinValue).Total,105);});
  Check("breakdown daily scopes and subsets match observed totals",delegate{var l=new UsageLedger();l.Accept("s",Meta("turn_context","2026-10-15T12:00:00Z","gpt-a",@"C:\Alpha"));l.Accept("s",Event(100,5,"2026-10-15T12:00:00Z",100,80,"null"));l.Accept("s",Meta("turn_context",b,"gpt-b",@"C:\Beta"));l.Accept("s",Event(150,10,b,150,100,"null"));foreach(var scope in new[]{DateTime.MinValue,new DateTime(2026,10,17)}){var all=l.TotalFor(scope);Eq(l.Models.Values.Sum(g=>UsageLedger.TotalForDays(g.Days,scope).Total),all.Total);Eq(l.Models.Values.Sum(g=>UsageLedger.TotalForDays(g.Days,scope).Cached),all.Cached);}Eq(Group(l.Models,"gpt-b",new DateTime(2026,10,17)).Total,55);});
  Check("older metadata replay cannot rewind live attribution",delegate{var l=new UsageLedger();l.Accept("s",Meta("turn_context",b,"gpt-b",@"C:\Beta"));l.Accept("s",E(100,5,b));l.Accept("s",Meta("turn_context",a,"gpt-a",@"C:\Alpha"));l.Accept("s",E(150,10,c));Eq(Group(l.Models,"gpt-b",DateTime.MinValue).Total,160);Eq(l.Models.Count,1);});
  string dir=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-fixtures-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);
  try {
   Check("collector follows appends and warm restart reads zero bytes",delegate{
    string home=Path.Combine(dir,"codex"),data=Path.Combine(dir,"data");Directory.CreateDirectory(Path.Combine(home,"sessions"));
    string p=Path.Combine(home,"sessions","rollout-01234567-1234-1234-1234-012345678901.jsonl");File.WriteAllText(p,E(100,5,a)+"\n",new UTF8Encoding(false));
    using(var collector=new Collector(home,data)){collector.Start();Wait(()=>collector.GetSnapshot().Recorded.Total==105);File.AppendAllText(p,E(150,10,b)+"\n",new UTF8Encoding(false));Wait(()=>collector.GetSnapshot().Recorded.Total==160);}
    using(var collector=new Collector(home,data)){collector.Start();Wait(()=>collector.GetSnapshot().Recorded.Total==160&&!collector.GetSnapshot().Indexing);Eq(collector.GetSnapshot().Bytes,0);}
   });
   Check("collector pause catches up after resume",delegate{
    string home=Path.Combine(dir,"pause-home"),data=Path.Combine(dir,"pause-data");Directory.CreateDirectory(Path.Combine(home,"sessions"));string p=Path.Combine(home,"sessions","one.jsonl");File.WriteAllText(p,E(100,5,a)+"\n",new UTF8Encoding(false));
    using(var collector=new Collector(home,data)){collector.Start();Wait(()=>collector.GetSnapshot().Recorded.Total==105);collector.Pause(true);Wait(()=>collector.GetSnapshot().Paused);File.AppendAllText(p,E(150,10,b)+"\n",new UTF8Encoding(false));Thread.Sleep(800);Eq(collector.GetSnapshot().Recorded.Total,105);collector.Pause(false);Wait(()=>collector.GetSnapshot().Recorded.Total==160);}
   });
   Check("collector checkpoints metadata-only appends for the next usage after restart",delegate{
    string home=Path.Combine(dir,"metadata-home"),data=Path.Combine(dir,"metadata-data");Directory.CreateDirectory(Path.Combine(home,"sessions"));string p=Path.Combine(home,"sessions","one.jsonl");File.WriteAllText(p,Meta("turn_context",a,"gpt-a",@"C:\Alpha")+"\n"+E(100,5,a)+"\n",new UTF8Encoding(false));
    using(var collector=new Collector(home,data)){collector.Start();Wait(()=>collector.GetSnapshot().Recorded.Total==105&&!collector.GetSnapshot().Indexing);long before=collector.GetSnapshot().Bytes;File.AppendAllText(p,Meta("turn_context",b,"gpt-b",@"C:\Beta")+"\n",new UTF8Encoding(false));Wait(()=>collector.GetSnapshot().Bytes>before);}
    File.AppendAllText(p,E(150,10,c)+"\n",new UTF8Encoding(false));using(var collector=new Collector(home,data)){collector.Start();Wait(()=>collector.GetSnapshot().Recorded.Total==160&&!collector.GetSnapshot().Indexing);Eq(collector.GetSnapshot().Models.Single(x=>x.Id=="gpt-a").Recorded.Total,105);Eq(collector.GetSnapshot().Models.Single(x=>x.Id=="gpt-b").Recorded.Total,55);}
   });
   Check("snapshot model sums match Today Week and Recorded",delegate{
    string home=Path.Combine(dir,"scope-home"),data=Path.Combine(dir,"scope-data");Directory.CreateDirectory(Path.Combine(home,"sessions"));string old=DateTime.Today.AddDays(-8).AddHours(12).ToUniversalTime().ToString("O"),week=DateTime.Today.AddDays(-2).AddHours(12).ToUniversalTime().ToString("O"),today=DateTime.Today.AddHours(12).ToUniversalTime().ToString("O");
    File.WriteAllText(Path.Combine(home,"sessions","scope.jsonl"),E(100,5,old)+"\n"+Meta("turn_context",week,"gpt-a",@"C:\Alpha")+"\n"+E(150,10,week)+"\n"+Meta("turn_context",today,"gpt-b",@"C:\Beta")+"\n"+E(180,15,today)+"\n",new UTF8Encoding(false));
    using(var collector=new Collector(home,data)){collector.Start();Wait(()=>collector.GetSnapshot().Recorded.Total==195&&!collector.GetSnapshot().Indexing);var snap=collector.GetSnapshot();Eq(snap.Today.Total,35);Eq(snap.Week.Total,90);Eq(snap.Models.Sum(x=>x.Today.Total),snap.Today.Total);Eq(snap.Models.Sum(x=>x.Week.Total),snap.Week.Total);Eq(snap.Models.Sum(x=>x.Recorded.Total),snap.Recorded.Total);}
   });
   Check("restart retains aggregates and replay identities",delegate{string p=Path.Combine(dir,"cache.db");using(var state=new SavedState()){state.Ledger.Accept("s",E(100,5,a));Store.Save(p,state);}using(var loaded=Store.Load(p)){Eq(loaded.Ledger.TotalFor(DateTime.MinValue).Total,105);loaded.Ledger.Accept("s",E(100,5,a));loaded.Ledger.Accept("fork",E(100,5,a));Eq(loaded.Ledger.TotalFor(DateTime.MinValue).Total,105);}});
   Check("atomic checkpoint replaces previous data",delegate{string p=Path.Combine(dir,"atomic.db");using(var state=new SavedState()){Store.Save(p,state);state.Ledger.Accept("s",E(100,5,a));Store.Save(p,state);}using(var loaded=Store.Load(p))Eq(loaded.Ledger.Events,1);});
   Check("corrupt checkpoint rebuilds safely",delegate{string p=Path.Combine(dir,"corrupt.db");File.WriteAllText(p,"broken");using(var loaded=Store.Load(p))Eq(loaded.Ledger.Events,0);});
   Check("checkpoint moves replay identities out of memory",delegate{string p=Path.Combine(dir,"compact.db");using(var state=new SavedState()){state.Ledger.Accept("s",E(100,5,a));Eq(state.Ledger.Seen.Count,1);Store.Save(p,state);Eq(state.Ledger.Seen.Count,0);state.Ledger.Accept("fork",E(100,5,a));Eq(state.Ledger.TotalFor(DateTime.MinValue).Total,105);}});
   Check("breakdowns and metadata survive checkpoint including metadata-only append",delegate{string p=Path.Combine(dir,"breakdown.db");using(var state=new SavedState()){state.Ledger.Accept("s",Meta("session_meta",a,null,@"C:\Alpha"));state.Ledger.Accept("s",E(100,5,a));state.Ledger.Accept("s",Meta("turn_context",b,"gpt-b",@"C:\Beta"));Store.Save(p,state);}using(var state=Store.Load(p)){state.Ledger.Accept("s",E(150,10,c));Eq(Group(state.Ledger.Models,UsageLedger.UnknownId,DateTime.MinValue).Total,105);Eq(Group(state.Ledger.Models,"gpt-b",DateTime.MinValue).Total,55);}});
   Check("existing v3 cache ignores removed project fields without reindex or lost totals",delegate{
    string p=Path.Combine(dir,"project-removal-v3.db");var serializer=new JavaScriptSerializer();
    using(var prior=new SavedState()){
     prior.Ledger.Accept("s",Meta("turn_context",a,"gpt-a",null));prior.Ledger.Accept("s",E(100,5,a));string day=DateTime.Parse(a).ToLocalTime().ToString("yyyy-MM-dd");prior.Ledger.LegacyDays[day]=new Tokens {Input=200,Output=5};prior.Ledger.ReconcileLegacy();prior.Cursors["retained.jsonl"]=new LineCursor {Offset=777,LastWriteTicks=12345};
     var root=(Dictionary<string,object>)serializer.DeserializeObject(serializer.Serialize(prior));var ledger=(Dictionary<string,object>)root["Ledger"];ledger["Projects"]=new Dictionary<string,object>{{"old-path",new {Id=@"C:\RemovedPath",Label="RemovedPath",Days=new Dictionary<string,Tokens>{{day,new Tokens {Input=305,Output=5}}}}}};
     var sessions=(Dictionary<string,object>)ledger["Sessions"];var session=(Dictionary<string,object>)sessions["s"];session["ProjectId"]=@"C:\RemovedPath";session["ProjectLabel"]="RemovedPath";session["ProjectAt"]=a;
     using(var db=new ReplayDatabase(p))db.Save(serializer.Serialize(root),prior.Ledger.Seen.Keys);
    }
    using(var loaded=Store.Load(p)){
     if(Store.Recovered)throw new Exception("valid existing cache was rebuilt");Eq(loaded.Version,2);Eq(loaded.Cursors["retained.jsonl"].Offset,777);Eq(loaded.Ledger.TotalFor(DateTime.MinValue).Total,310);Eq(Group(loaded.Ledger.Models,"gpt-a",DateTime.MinValue).Total,105);
     loaded.Ledger.Accept("s",E(100,5,a));loaded.Ledger.Accept("fork",E(100,5,a));loaded.Ledger.Accept("s",E(150,10,b));loaded.Ledger.ReconcileLegacy();Eq(loaded.Ledger.TotalFor(DateTime.MinValue).Total,365);Eq(Group(loaded.Ledger.Models,"gpt-a",DateTime.MinValue).Total,160);Eq(loaded.Ledger.Models.Values.Sum(g=>UsageLedger.TotalForDays(g.Days,DateTime.MinValue).Total),365);Store.Save(p,loaded);
    }
    string current=ReplayDatabase.LoadReadOnly(p);if(current.IndexOf("RemovedPath",StringComparison.Ordinal)>=0||current.IndexOf("Project",StringComparison.Ordinal)>=0)throw new Exception("obsolete project fields survived checkpoint");
   });
   Check("v3 reindex preserves unavailable legacy history without changing v2",delegate{
    string home=Path.Combine(dir,"migration-home"),data=Path.Combine(dir,"migration-data");Directory.CreateDirectory(Path.Combine(home,"sessions"));Directory.CreateDirectory(data);string oldPath=Path.Combine(data,"usage-v2.db");
    using(var old=new SavedState()){old.Version=1;old.Ledger.Accept("available",E(100,5,a));old.Ledger.Accept("missing",E(200,5,b));Store.Save(oldPath,old);}byte[] oldBytes=File.ReadAllBytes(oldPath);
    string file=Path.Combine(home,"sessions","available.jsonl");File.WriteAllText(file,Meta("turn_context",a,"gpt-a",@"C:\Alpha")+"\n"+E(100,5,a)+"\n",new UTF8Encoding(false));
    using(var collector=new Collector(home,data)){collector.Start();Wait(()=>collector.GetSnapshot().Recorded.Total==310&&!collector.GetSnapshot().Indexing);var snap=collector.GetSnapshot();Eq(snap.Models.Single(x=>x.Id=="gpt-a").Recorded.Total,105);Eq(snap.Models.Single(x=>x.Id==UsageLedger.UnknownId).Recorded.Total,205);Eq(snap.Models.Sum(x=>x.Recorded.Total),310);}
    if(!oldBytes.SequenceEqual(File.ReadAllBytes(oldPath)))throw new Exception("legacy database changed");
    using(var collector=new Collector(home,data)){collector.Start();Wait(()=>collector.GetSnapshot().Recorded.Total==310&&!collector.GetSnapshot().Indexing);Eq(collector.GetSnapshot().Bytes,0);}
    File.AppendAllText(file,E(150,10,c)+"\n",new UTF8Encoding(false));
    using(var collector=new Collector(home,data)){collector.Start();Wait(()=>collector.GetSnapshot().Recorded.Total==365&&!collector.GetSnapshot().Indexing);Eq(collector.GetSnapshot().Models.Single(x=>x.Id==UsageLedger.UnknownId).Recorded.Total,205);}
    File.WriteAllText(Path.Combine(home,"sessions","missing.jsonl"),Meta("turn_context",b,"gpt-b",@"C:\Beta")+"\n"+E(200,5,b)+"\n",new UTF8Encoding(false));
    using(var collector=new Collector(home,data)){collector.Start();Wait(()=>collector.GetSnapshot().Models.Any(x=>x.Id=="gpt-b")&&!collector.GetSnapshot().Indexing);Eq(collector.GetSnapshot().Recorded.Total,365);Eq(collector.GetSnapshot().Models.Sum(x=>x.Recorded.Total),365);if(collector.GetSnapshot().Models.Any(x=>x.Id==UsageLedger.UnknownId))throw new Exception("recovered legacy history counted twice");}
   });
   Check("an unreadable legacy checkpoint cannot silently become an empty migrated cache",delegate{string old=Path.Combine(dir,"bad-legacy.db"),fresh=Path.Combine(dir,"bad-legacy-v3.db");using(var db=new ReplayDatabase(old))db.Save("{broken",new string[0]);byte[] before=File.ReadAllBytes(old);bool threw=false;try{using(var state=Store.Load(fresh,old)){} }catch(ArgumentException){threw=true;}if(!threw)throw new Exception("migration failure was hidden");if(!before.SequenceEqual(File.ReadAllBytes(old)))throw new Exception("legacy file changed");using(var db=new ReplayDatabase(fresh))if(db.Load()!=null)throw new Exception("empty migration checkpoint saved");});
   Check("partial newline is retried exactly once",delegate{string p=Path.Combine(dir,"split.jsonl");File.WriteAllText(p,"one\ntw",new UTF8Encoding(false));var cur=new LineCursor();int n=0;cur.Read(p,delegate(string s){n++;});Eq(n,1);Eq(cur.Offset,4);File.AppendAllText(p,"o\n",new UTF8Encoding(false));cur.Read(p,delegate(string s){n++;});Eq(n,2);Eq(cur.Offset,8);cur.Read(p,delegate(string s){n++;});Eq(n,2);});
   Check("oversized line skips safely and next line survives",delegate{string p=Path.Combine(dir,"large.jsonl");File.WriteAllText(p,new string('x',600000)+"\nok\n",new UTF8Encoding(false));var cur=new LineCursor();int n=0;cur.Read(p,delegate(string s){if(s=="ok")n++;});Eq(n,1);Eq(cur.Offset,new FileInfo(p).Length);});
   Check("truncated file starts over",delegate{string p=Path.Combine(dir,"reset.jsonl");File.WriteAllText(p,"previous\n");var cur=new LineCursor();cur.Read(p,delegate{});File.WriteAllText(p,"new\n",new UTF8Encoding(false));int n=0;cur.Read(p,delegate{n++;});Eq(n,1);Eq(cur.Offset,4);});
   Check("same length replacement is detected",delegate{string p=Path.Combine(dir,"replace.jsonl");File.WriteAllText(p,"old\n",new UTF8Encoding(false));var cur=new LineCursor();cur.Read(p,delegate{});File.WriteAllText(p,"new\n",new UTF8Encoding(false));int n=0;cur.Read(p,delegate(string line){if(line=="new")n++;});Eq(n,1);});
   Check("boundary checkpoint stores a hash, never transcript bytes",delegate{string p=Path.Combine(dir,"privacy.jsonl");File.WriteAllText(p,"private conversation text\n",new UTF8Encoding(false));var cur=new LineCursor();cur.Read(p,delegate{});Eq(Convert.FromBase64String(cur.Boundary).Length,32);if(cur.Boundary==Convert.ToBase64String(File.ReadAllBytes(p)))throw new Exception("raw transcript stored");});
   Check("database error does not advance cursor or create a baseline",delegate{string p=Path.Combine(dir,"retry.jsonl");File.WriteAllText(p,Event(100000,50,a,12,0,"null")+"\n",new UTF8Encoding(false));var ledger=new UsageLedger();var db=new ReplayDatabase(Path.Combine(dir,"retry.db"));ledger.Replay=db;db.Dispose();var cur=new LineCursor();bool threw=false;try{cur.Read(p,line=>ledger.Accept("s",line));}catch(DatabaseException){threw=true;}if(!threw)throw new Exception("database failure swallowed");Eq(cur.Offset,0);Eq(ledger.Sessions.Count,0);ledger.Replay=null;cur.Read(p,line=>ledger.Accept("s",line));Eq(ledger.TotalFor(DateTime.MinValue).Total,17);});
  } finally { Directory.Delete(dir,true); }
  Console.WriteLine(passed+" passed, "+failed+" failed");return failed==0?0:1;
 }
 static void Wait(Func<bool> predicate){DateTime end=DateTime.UtcNow.AddSeconds(10);while(DateTime.UtcNow<end){if(predicate())return;Thread.Sleep(40);}throw new Exception("timed out waiting for observed usage");}
}
